window.__CAT__=window.__CAT__||[];window.__CAT__.push([{"no": 31, "id": "jMnmevfcnYo", "title": "The Canary of the general's palm", "title_zh": "将军掌中的金丝雀 (The Canary of the general's palm)", "duration": "00:06:03", "link": "https://www.youtube.com/watch?v=jMnmevfcnYo", "enriched": true, "lines": [{"ts": "00:00:00", "text": "给他妈！", "speaker": "公子", "tone": "撒娇", "sound": []}, {"ts": "00:00:02", "text": "干嘛的。", "speaker": "公子", "tone": "撒娇", "sound": []}, {"ts": "00:00:04", "text": "放开他。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "吴副官。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "把这个绑起来带过去。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:00:10", "text": "好好找找不着。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "管他妈谁家公子，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "老子们一枪崩了他。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:16", "text": "就他，左膀右臂都击毙了。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "走。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:20-00:00:23", "text": "快点。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:00:26", "text": "老子。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:29", "text": "你好。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "这就是你所谓的不想靠我，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "一定要做出名堂来给我看看。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:00:40", "text": "一出戏还没唱上，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "就让这种混蛋给缠上。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "如果今天我不来，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "你是不是就得跟他走了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "跟我回话。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "你要是不回去，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "这梨园春的人，有一个算一个，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "老子都崩了。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "你看我敢不敢。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "一路上都这么沉默，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "怎么？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "生气了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "梨园春以后还是别去了。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:01:37", "text": "你要是喜欢唱戏，", "speaker": "公子", "tone": "宠溺", "sound": []}, {"ts": "00:01:40", "text": "在家里唱也是一样。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:43", "text": "这世道这么乱，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "戏园子里面鱼龙混杂的。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "这次正好是我撞见，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "下次要再有人想占便宜怎么办。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "怪听话。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:01:57", "text": "乖乖听话。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "之前在上海定做的旗袍到了，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "你待会去试试。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:05", "text": "好好看。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "好好说你不听了是吧？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:10", "text": "就非他妈今天要顶嘴是吧？", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:02:13", "text": "你过来。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:02:16", "text": "过来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "好说。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "倒说都不听。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "你哪来这么多脾气。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "说话。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "不说什么？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "你今天就试试，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "到底是你嘴硬，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "还是我这戒尺硬。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:02:55", "text": "站起来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "面对我。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "是你自己动手，还是我来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "一。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "二。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "三。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "刚刚那个王八蛋跑哪了？", "speaker": "公子", "tone": "询问", "sound": []}, {"ts": "00:03:25", "text": "这里吗？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "还是这里。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:33", "text": "这里。", "speaker": "公子", "tone": "责备", "sound": []}, {"ts": "00:03:36", "text": "又或者是，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "这里。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "这才几下，", "speaker": "公子", "tone": "温柔", "sound": []}, {"ts": "00:03:47", "text": "怎么就哭了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "刚刚打屁股打这么狠，", "speaker": "公子", "tone": "温柔", "sound": []}, {"ts": "00:03:55", "text": "可你这辈子都没哭，", "speaker": "公子", "tone": "温柔", "sound": []}, {"ts": "00:04:00", "text": "怎么还越哭越厉害了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:02", "text": "不是嫌弃你。", "speaker": "公子", "tone": "责备", "sound": []}, {"ts": "00:04:05", "text": "又怎么会嫌弃你。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "过来。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:04:10", "text": "今天下手确实重了点。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "让我看看。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "不是我非要把你圈在府里面。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "可是你看现在世道这么乱。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:25", "text": "到处都在打仗。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "你除了我以外的话可怎么办。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "你就安安稳稳地待在府上。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "没事呢？", "speaker": "公子", "tone": "询问", "sound": []}, {"ts": "00:04:37", "text": "咱就跟别的太太喝喝茶。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:04:40", "text": "喝喝咖啡。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "打打麻将。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "你说这又啥不好？", "speaker": "公子", "tone": "责备", "sound": []}, {"ts": "00:04:50", "text": "不想做尽此劝。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "怕回头不要你。", "speaker": "公子", "tone": "温柔", "sound": []}, {"ts": "00:04:59", "text": "你这整天胡思乱想什么呢？", "speaker": "公子", "tone": "询问", "sound": []}, {"ts": "00:05:03", "text": "是我对你不够好吗？", "speaker": "公子", "tone": "询问", "sound": []}, {"ts": "00:05:07", "text": "还是。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "我夜里不在。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "才让你白天有功夫。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:19", "text": "胡思乱想的。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:23", "text": "来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "我的宝贝。", "speaker": "公子", "tone": "撒娇", "sound": []}, {"ts": "00:05:31", "text": "过来。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:05:35", "text": "刚刚那几下打得也不狠。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:38", "text": "怎么小兔子都红了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:41", "text": "我听你柔柔。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "这里是不是也红了。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "不如。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "夫人现在就这个样子。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "将那出。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "大闹销金帐。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "再唱一回。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "就唱得好了。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "我便给你。", "speaker": "公子", "tone": "平静", "sound": []}], "scene": "将军夫人救援型。说话者是护着你的「将军／老爷」（自称「老子」），你是他府上的夫人（小叫「小兔子」）。情境起点：你在梨园春唱戏被人纠缠，他带人把你抢回来，先因你嘴硬、敢顶嘴而打屁股娇训，又担心你被那混蛋碰过而检查身体，最后转为温柔安抚，说把你圈在府里、哄你再唱一回就给奖励。整体是「吃醋救人＋打屁股管娇后的宠溺」，基调霸道、占有、甜。", "behaviors": [{"desc": "让人放开你、把纠缠你的混蛋带走"}, {"desc": "威胁你不回去就把梨园春的人「全崩了」"}, {"desc": "说以后别去梨园春，上海定的旗袍到了让你去试"}, {"desc": "笑你嘴硬，说让你试试「嘴硬还是戒指硬」"}, {"desc": "打你屁股、数落你「怎么几下就哭了」"}, {"desc": "说下手重了，让你过来让他看看伤"}, {"desc": "说要把你圈在府里安稳待着"}, {"desc": "哄你「小兔子都哄了」，说唱好了就给奖励"}], "tone_summary": "（自动）公子视角独白，语气以平静、命令、询问为主，题材偏古风。", "genre_tags": ["古风", "治愈", "敏感"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被公子倾诉/照顾/管教的一方（你）", "signature_elements": ["戒尺", "绑", "打屁股"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "梨园春的后台，几个兵痞正拽着一个年轻戏子往外拖。他穿着军装走进来，靴声在木地板上叩响，眼神冷得像刀。他抬手，拦下了那些人。"}, {"type": "line", "speaker": "公子", "text": "给他妈！干嘛的。放开他。吴副官。把这个绑起来带过去。好好找找不着。管他妈谁家公子，老子们一枪崩了他。就他，左膀右臂都击毙了。走。快点。老子。你好。"}, {"type": "narr", "text": "兵痞们灰溜溜地被押走。他转身，看着那个惊魂未定的人，语气带着压不住的怒意。"}, {"type": "line", "speaker": "公子", "text": "这就是你所谓的不想靠我，一定要做出名堂来给我看看。一出戏还没唱上，就让这种混蛋给缠上。如果今天我不来，你是不是就得跟他走了？跟我回话。"}, {"type": "narr", "text": "她低着头不说话。他上前一步，声音沉下来。"}, {"type": "line", "speaker": "公子", "text": "你要是不回去，这梨园春的人，有一个算一个，老子都崩了。你看我敢不敢。"}, {"type": "narr", "text": "她终于被他带回府上。一路上，她始终沉默。他坐在车里，侧头看她，语气缓和了些。"}, {"type": "line", "speaker": "公子", "text": "一路上都这么沉默，怎么？生气了？梨园春以后还是别去了。你要是喜欢唱戏，在家里唱也是一样。这世道这么乱，戏园子里面鱼龙混杂的。这次正好是我撞见，下次要再有人想占便宜怎么办。怪听话。乖乖听话。"}, {"type": "narr", "text": "她忽然开口，说要继续唱戏。他眉头一皱，语气带着冷。"}, {"type": "line", "speaker": "公子", "text": "之前在上海定做的旗袍到了，你待会去试试。好好看。好好说你不听了是吧？就非他妈今天要顶嘴是吧？你过来。过来。好说。倒说都不听。你哪来这么多脾气。说话。不说什么？"}, {"type": "line", "speaker": "公子", "text": "你今天就试试，到底是你嘴硬，还是我这戒尺硬。站起来。面对我。是你自己动手，还是我来。一。二。三。"}, {"type": "narr", "text": "她咬着牙没有动。他沉着脸，手里的戒尺一下一下落下来。她始终没有躲，却也没有哭。"}, {"type": "line", "speaker": "公子", "text": "刚刚那个王八蛋跑哪了？这里吗？还是这里。这里。又或者是，这里。这才几下，怎么就哭了？刚刚打屁股打这么狠，可你这辈子都没哭，怎么还越哭越厉害了？不是嫌弃你。又怎么会嫌弃你。"}, {"type": "narr", "text": "他放下戒尺，伸手把人拉过来，语气带着后悔的心疼。"}, {"type": "line", "speaker": "公子", "text": "过来。今天下手确实重了点。来。让我看看。不是我非要把你圈在府里面。可是你看现在世道这么乱。到处都在打仗。你除了我以外的话可怎么办。"}, {"type": "line", "speaker": "公子", "text": "你就安安稳稳地待在府上。没事呢？咱就跟别的太太喝喝茶。喝喝咖啡。打打麻将。你说这又啥不好？不想做尽此劝。怕回头不要你。你这整天胡思乱想什么呢？是我对你不够好吗？还是。我夜里不在。才让你白天有功夫。胡思乱想的。"}, {"type": "narr", "text": "她低着头，小声说，怕他嫌她。他叹了口气，语气软下来，带着无奈的宠溺。"}, {"type": "line", "speaker": "公子", "text": "来。我的宝贝。过来。刚刚那几下打得也不狠。怎么小兔子都红了？我听你柔柔。这里是不是也红了。不如。夫人现在就这个样子。将那出。大闹销金帐。再唱一回。就唱得好了。我便给你。"}, {"type": "narr", "text": "她红着脸，轻轻地靠进他怀里。他低头看着她，眼底终于有了笑意。乱世里的金丝雀，也许飞不出那座府邸，但至少，笼子是他亲手搭的，笼里是她最安稳的巢。"}]}, {"no": 32, "id": "DfF2fzX_-V0", "title": "The SP video in the computer was found by your boss", "title_zh": "电脑里的责罚视频被老板发现了 (The SP video in the computer was found by your boss)", "duration": "00:08:55", "link": "https://www.youtube.com/watch?v=DfF2fzX_-V0", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我这边都结束了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "你把剩下的发给我。", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:00:20", "text": "我帮你一起做。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "电脑死机，发不出去。", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:00:36", "text": "我记得我之前教过你怎么设置自动保存。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "那问题不大，来我帮你看看。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:00:53", "text": "哎呀，你是说——", "speaker": "上司", "tone": "撒娇", "sound": []}, {"ts": "00:00:56", "text": "磁盘都满了，电脑能不卡吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:00:59", "text": "你把这些东西放到别的盘就好了。", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:01:03", "text": "你看，你看这个。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "这个。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "怎么都是视频文件啊？真的是什么？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "惩罚训诫。", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:01:16", "text": "SP打屁股。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:19", "text": "资料在这儿。然后——", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "先把资料发过去吧。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "好了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "那走吧，下班。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "我开车送你回去。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "想聊几句啊！", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "聊什么？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "DS关系吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:01:54", "text": "经验什么？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "经验？我也懂这些。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:58-00:02:20", "text": "那说说你的理解吧。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "嗯。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "惩罚。", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:02:27", "text": "训诫。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "在DS关系里，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "重点并不是训诫和疼痛，", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:02:36", "text": "而是爱和臣服。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "你不应该因为恋痛或者预防，", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:02:42", "text": "而去尝试。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:44", "text": "而是要懂得臣服于一个人。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "令你踏实。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:49", "text": "引领你前行。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "而会鼓励你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "鼓励你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "爱好平凡，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "天高海阔，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "却还能，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "保护你一颗赤子之心的人。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "懂吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:03:07", "text": "所以最近是脑袋里面，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:09", "text": "装了这些事情，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "才没把工作放在心上的。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "对吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:03:16", "text": "那作为你的直属上司，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "发现你工作的效率明显下降，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "脑袋里面整天想着有的没的，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "我是要严厉地批评你的。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "因为我之前对你的了解，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "我觉得这样足够了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "但是现在我了解你更多了一些，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "我觉得除此之外，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "你可能还需要一些，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "肉体上的严厉惩罚，", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:03:48", "text": "才能真正记住教训。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "你觉得呢？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:03:54", "text": "说什么大蠢蛋。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "我主张严厉地惩罚你。", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:04:01", "text": "那你希望我主张要怎么严厉地惩罚你呢？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:04:05", "text": "要像视频那样，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "打你的屁股吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:04:12", "text": "这样你能够记住教训，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:15", "text": "不再犯吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:04:18", "text": "好。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "自己趴到腿上来。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "你最近总是在工作的时候走神。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "之前我还以为是你工作太累了。", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:04:44", "text": "现在看来，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:48", "text": "是脑子里面装了不该有的东西。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:53", "text": "今天先罚你三十下。", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:04:57", "text": "服不服？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "服气就好。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "以后还敢不敢？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "说话。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:24", "text": "不要摆出一副委屈的样子。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "我罚你罚错了吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:05:35", "text": "大蠢蛋。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:44", "text": "没有就好好地反省。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:49", "text": "以后还敢不敢不专心工作。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:54", "text": "看起来乖乖巧巧、努力用心，", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:05:58", "text": "其实脑子里面，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:03", "text": "都在想一些，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "有的没的。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:12", "text": "是不是？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "所以以后上班的时候，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "专心工作。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:23", "text": "再敢这个样子，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:26", "text": "就不是三十下这么简单了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:29", "text": "记住了没？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:32", "text": "大蠢蛋。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:35", "text": "记住了没？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:39", "text": "对。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "好好地记住。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:43", "text": "起来吧。", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:06:45", "text": "怎么还哭了？", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:06:47", "text": "这么久了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "好了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:52", "text": "罚过了，", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:06:55", "text": "这件事情就过去了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:58", "text": "还害羞了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:03", "text": "没想到我也懂这些。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:14", "text": "之前也会很喜欢我。", "speaker": "上司", "tone": "宠溺", "sound": []}, {"ts": "00:07:20", "text": "既然这样的话，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "以后由我，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "来做那个让你踏实的人。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:30", "text": "可以吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:07:34", "text": "是你抬起头了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:36", "text": "嘴巴张这么大。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:38", "text": "其实呢，", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:07:41", "text": "我也注意你很久了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:43", "text": "工作很认真，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:45", "text": "待人和气，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:48", "text": "也很善良。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "虽然有时候迷迷糊糊的吧。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:52", "text": "不过，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "你蛮可爱的。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:57", "text": "所以，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:59", "text": "昨晚你朋友，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:02", "text": "我来照顾你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:04", "text": "来保护你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "当然了，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:09", "text": "也会引导你和训诫你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:11", "text": "这样好不好？", "speaker": "上司", "tone": "撒娇", "sound": []}, {"ts": "00:08:14", "text": "傻丫头？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:08:16", "text": "你可要想好了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:18", "text": "从今以后，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:21", "text": "你负责向下生长，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "我就负责，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:25", "text": "帮你修剪枝丫。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:28", "text": "以后要是再做错事情，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:30", "text": "公司里的主管，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:33", "text": "会严肃地批评。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:35", "text": "回到家，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:37", "text": "哄一哄，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:40", "text": "打你的小屁股。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:42", "text": "听到了没？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "疼。", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:08:45", "text": "都没用力。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "疼。", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:08:45", "text": "肚子饿了没？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "带你去吃夜宵好不好？", "speaker": "上司", "tone": "撒娇", "sound": []}], "scene": "职场 S 属性调娇。说话者是你「直属上司／老板」，你是他手下员工。情境起点：他来帮你修死机的电脑，意外发现你盘里存着 SP（打屁股）视频，借机把你叫上车，先给你上一堂「DS 关系里重点是爱与臣服」的课，再以「工作效率下降」为由把你趴到腿上打屁股娇训，最后表白早就在意你、以后由他做让你踏实的人，并约法三章「公司严厉批评、回家打小屁股」。整体是「老板撞破小秘密后顺势调娇」，基调暧昧、掌控、甜。", "behaviors": [{"desc": "帮你看电脑、发现硬盘满了死机"}, {"desc": "发现你盘里存着 SP 视频文件"}, {"desc": "车上和你聊 DS 关系，讲重点在爱与臣服"}, {"desc": "让你自己趴到他腿上受罚"}, {"desc": "说先罚三十下，问你服不服"}, {"desc": "罚完让你起来，说「发过了就过去了」"}, {"desc": "表白早注意你很久，以后由他做让你踏实的人"}, {"desc": "问疼不疼、带你去吃宵夜"}], "tone_summary": "（自动）上司视角独白，语气以平静、询问、温柔为主，题材偏职场。", "genre_tags": ["职场", "治愈"], "genre_main": "职场", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被上司倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "办公室的灯还亮着。她对着电脑发呆，屏幕上的文档半天没动。身后传来脚步声，他俯身看了一眼，语气带着上级惯常的温和。"}, {"type": "line", "speaker": "上司", "text": "我这边都结束了。你把剩下的发给我，我帮你一起做。电脑死机，发不出去？我记得我之前教过你怎么设置自动保存。那问题不大，来，我帮你看看。哎呀，你是说——磁盘都满了，电脑能不卡吗？你把这些东西放到别的盘就好了。"}, {"type": "narr", "text": "他点开磁盘管理，鼠标划过那一长串文件名，动作忽然顿住了。她坐在旁边，脸色一下子白了。他转头看她，语气带着了然。"}, {"type": "line", "speaker": "上司", "text": "你看，你看这个。这个。怎么都是视频文件啊？真的是什么？惩罚训诫。SP打屁股。资料在这儿。然后——先把资料发过去吧。好了。那走吧，下班。我开车送你回去。"}, {"type": "narr", "text": "车里很安静。她坐在副驾，低着头不敢看他。他开着车，忽然开口，语气平静得像在聊一件很普通的事。"}, {"type": "line", "speaker": "上司", "text": "想聊几句啊！聊什么？DS关系吗？经验什么？经验？我也懂这些。那说说你的理解吧。嗯。惩罚。训诫。在DS关系里，重点并不是训诫和疼痛，而是爱和臣服。你不应该因为恋痛或者猎奇，而去尝试，而是要懂得臣服于一个人，令你踏实，引领你前行。"}, {"type": "narr", "text": "她听着他的话，心跳一点点加快。他顿了顿，声音低下来，带着认真的分量。"}, {"type": "line", "speaker": "上司", "text": "而会鼓励你，鼓励你——爱好平凡，天高海阔，却还能保护你一颗赤子之心的人。懂吗？所以最近是脑袋里面装了这些事情，才没把工作放在心上的，对吗？那作为你的直属上司，发现你工作的效率明显下降，脑袋里面整天想着有的没的，我是要严厉地批评你的。"}, {"type": "narr", "text": "她低下头，脸红得厉害。他侧头看她一眼，语气带着一点意味深长的转折。"}, {"type": "line", "speaker": "上司", "text": "因为我之前对你的了解，我觉得这样足够了。但是现在我了解你更多了一些，我觉得除此之外，你可能还需要一些肉体上的严厉惩罚，才能真正记住教训。你觉得呢？说什么大蠢蛋。我主张严厉地惩罚你。那你希望我主张要怎么严厉地惩罚你呢？要像视频那样，打你的屁股吗？这样你能够记住教训，不再犯吗？"}, {"type": "narr", "text": "她声音细若蚊蚋，好半天才挤出两个字。他听完，方向盘一转，把车停在路边，语气带着不容拒绝的从容。"}, {"type": "line", "speaker": "上司", "text": "好。自己趴到腿上来。你最近总是在工作的时候走神，之前我还以为是你工作太累了。现在看来，是脑子里面装了不该有的东西。今天先罚你三十下。服不服？服气就好。以后还敢不敢？说话。不要摆出一副委屈的样子，我罚你罚错了吗？大蠢蛋。"}, {"type": "narr", "text": "她趴在车座上，咬着唇，一下一下地挨着。他一边打，一边带着恨铁不成钢的数落。"}, {"type": "line", "speaker": "上司", "text": "没有就好好地反省。以后还敢不敢不专心工作？看起来乖乖巧巧、努力用心，其实脑子里面，都在想一些有的没的，是不是？所以以后上班的时候，专心工作。再敢这个样子，就不是三十下这么简单了。记住了没？大蠢蛋。记住了没？对，好好地记住。"}, {"type": "narr", "text": "三十下打完，他停下手，语气软下来。她趴在座位上，肩膀轻轻抖着。"}, {"type": "line", "speaker": "上司", "text": "起来吧。怎么还哭了？这么久了。好了。罚过了，这件事情就过去了。还害羞了？没想到我也懂这些。之前也会很喜欢我？既然这样的话，以后由我，来做那个让你踏实的人。可以吗？"}, {"type": "narr", "text": "她抬起头，眼睛红红的，愣愣地看着他。他看着她这副模样，忍不住笑了，语气带着认真的温柔。"}, {"type": "line", "speaker": "上司", "text": "是你抬起头了，嘴巴张这么大。其实呢，我也注意你很久了。工作很认真，待人和气，也很善良。虽然有时候迷迷糊糊的吧。不过，你蛮可爱的。所以，昨晚你朋友——我来照顾你，来保护你。当然了，也会引导你和训诫你。这样好不好？傻丫头？"}, {"type": "narr", "text": "她红着脸，轻轻点了一下头。他看着她，眼底带着纵容的笑意，说出那句郑重的承诺。"}, {"type": "line", "speaker": "上司", "text": "你可要想好了。从今以后，你负责向下生长，我就负责，帮你修剪枝丫。以后要是再做错事情，公司里的主管，会严肃地批评。回到家，哄一哄，打你的小屁股。听到了没？疼？都没用力。疼。肚子饿了没？带你去吃夜宵，好不好？"}, {"type": "narr", "text": "她破涕为笑，眼睛亮亮的。他发动车子，朝她笑了笑。夜风从窗外灌进来，她靠进椅背，忽然觉得——原来被人接管、被人在意，是这样一种踏实的感觉。而明天上班，她大概会格外专心。"}]}, {"no": 33, "id": "fnEWYu9wk6k", "title": "The cat who loves you (tear warning)", "title_zh": "爱着你的那只猫（催泪预警） (The cat who loves you (tear warning))", "duration": "00:05:19", "link": "https://www.youtube.com/watch?v=fnEWYu9wk6k", "enriched": true, "lines": [{"ts": "00:00:00", "text": "这是一个小故事。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:02", "text": "猫有九条命。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:05", "text": "每一次死去，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "都是一次转身，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:11", "text": "为了换一个躯壳，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "来到你面前。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:17", "text": "九个十年，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "刚好够做完一生。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "现在是凌晨四点。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "再过一会儿，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "天就要亮了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "我找好了喜欢的地方。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:34", "text": "抱歉，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "最后的路程，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:40", "text": "不能让你陪着我了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "还记得我们第一次见面吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:46", "text": "你拿着罐头在树丛边，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "我一眼就瞧出了你的心思，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "想用一个罐头就把我骗走。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "天真的姑娘。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "后来啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "看你天天都来喂猫，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "没有一只猫咪上前，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "每次都等你离开之后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "他们才会出现，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "把罐头哄抢光。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "那我看你失落的样子就想，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "去哄哄你这个小姑娘吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "所以跟你回家，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "才不是为了固定粮仓。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "回到家之后你对我", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "说，从今以后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:50", "text": "我就是你的猫咪了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "其实我已经在野外，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "流浪两年了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "说来，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "你才是需要被人照顾的小孩子呢。", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:02:06", "text": "你学习很辛苦，", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:02:10", "text": "所以你在看书的时候，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "我选择趴在你的背上。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "其实我都有在背后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "默默看着你，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "陪着你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "后来，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "你把更多时间交给了工作，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "我很少看见你开心的样子，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "也很少再来闹我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "你带我搬去了自己的房子，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:41", "text": "给我换了更大的软垫，", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:02:43", "text": "但我还是喜欢趴在你的背上，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:02:46", "text": "压着你，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:49", "text": "直到你抱怨，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:52", "text": "腿都麻了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "喜欢看你笑着喊我的名字，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:02:57", "text": "揉揉我的脑袋，", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:03:00", "text": "用你的下巴，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "给我梳毛。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:03:06", "text": "喜欢在冬日，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:03:08", "text": "阳光正好的午后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "你眯着眼，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "和你一起晒太阳。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "我多想，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "能趴你再久一点，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "再久一点呢。", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:25", "text": "我先看不见，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "渐渐看不见。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:34", "text": "我先看不见，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:37-00:03:41", "text": "渐渐看不见。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "视力没有了依靠，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "也不能准确地判断跳跃的距离。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "在第七次跳沙发的时候，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "我摔下来了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:00", "text": "我就知道了，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我要走了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "你实际上对我说很羡慕我，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "能当一只猫咪，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "不会悲喜，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "也不会欣喜若狂。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "我这个淘气鬼。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:25", "text": "但是我是真的很爱你，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:04:30", "text": "所以这次就让我任性一回。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "下次见面，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "换我去找你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "等着那一天，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "我会，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "蹲在家门口。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "你回来的时候，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:48", "text": "我就滚到你脚边。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "你一定可以认出我，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:54", "text": "然后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "带我回家。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "对吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:05:02", "text": "姐姐。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:05", "text": "一定是。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:08", "text": "所以，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "再见了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "永远爱你的，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:05:15", "text": "猫咪。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "猫咪第一人称临终告白（催泪向）。说话者是一只陪伴你多年的猫（自称「猫咪」），你是它的人类「姐姐」。情境起点：它已是第九次转世、快走到生命尽头，在凌晨四点向你道别。它回忆初见你拿罐头灯、跟你回家后你把它当「弟弟」照顾，它默默陪你读书、趴你腿上晒太阳；第七次跳沙发摔下来它便知道自己要走了，最后许诺下被子还来做你的猫、蹲在家门口等你带它回家。整体是「宠物跨世陪伴」型温柔告白，基调治愈、感伤、极深情。", "behaviors": [{"desc": "回忆你拿罐头灯在树丛边、它一眼瞧出你的心思"}, {"desc": "跟你回家后，你说「从今以后我就是你弟弟了」"}, {"desc": "你学习辛苦，它选择趴在你背上陪你"}, {"desc": "喜欢冬日午后和你一起晒太阳、趴你久一点"}, {"desc": "第七次跳沙发摔下来，它知道「我要走了」"}, {"desc": "许诺下被子还来找你、蹲在家门口等你带它回家"}], "tone_summary": "（自动）他视角独白，语气以平静、宠溺、询问为主，题材偏古风。", "genre_tags": ["古风", "治愈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "凌晨四点，天还没有亮。我趴在窗台上，望着客厅里熟睡的你，在心里把想说的话，又默默念了一遍。"}, {"type": "line", "speaker": "他", "text": "这是一个小故事。猫有九条命。每一次死去，都是一次转身，为了换一个躯壳，来到你面前。"}, {"type": "narr", "text": "月光落在我身上。我低头舔了舔自己有些褪色的毛，忽然觉得，时间好像真的快到了。"}, {"type": "line", "speaker": "他", "text": "九个十年，刚好够做完一生。现在是凌晨四点。再过一会儿，天就要亮了。我找好了喜欢的地方。"}, {"type": "narr", "text": "我回过头，最后看了你一眼。你睡得很沉，呼吸均匀，被子一角还搭在你肩上。我轻声开口，像怕吵醒你。"}, {"type": "line", "speaker": "他", "text": "抱歉，最后的路程，不能让你陪着我了。还记得我们第一次见面吗？"}, {"type": "narr", "text": "那天的画面在我眼前浮现。树丛边，你蹲在那里，手里举着一罐罐头，眼睛亮亮地看着我。"}, {"type": "line", "speaker": "他", "text": "你拿着罐头在树丛边，我一眼就瞧出了你的心思。想用一个罐头就把我骗走。天真的姑娘。"}, {"type": "narr", "text": "我那时其实在心里笑你——我流浪了那么久，哪是那么容易上当的。可你偏偏，是那么认真的样子。"}, {"type": "line", "speaker": "他", "text": "后来啊！看你天天都来喂猫，没有一只猫咪上前。每次都等你离开之后，他们才会出现，把罐头哄抢光。"}, {"type": "narr", "text": "你蹲在空荡荡的树丛边，失落的样子，我到现在都记得。那一刻我就想，去哄哄你这个小姑娘吧。"}, {"type": "line", "speaker": "他", "text": "所以跟你回家，才不是为了固定粮仓。回到家之后，你对我说，从今以后，我就是你的猫咪了。"}, {"type": "narr", "text": "我那时想，真是个傻姑娘。明明是我自己选了你，你却郑重其事地宣告，好像给了我天大的名分。"}, {"type": "line", "speaker": "他", "text": "其实我已经在野外，流浪两年了。说来，你才是需要被人照顾的小孩子呢。"}, {"type": "narr", "text": "你学习很辛苦，总在书桌前坐到深夜。我不吵你，只是轻轻跳上你的背，趴在那里，假装睡觉。"}, {"type": "line", "speaker": "他", "text": "你学习很辛苦，所以你在看书的时候，我选择趴在你的背上。其实我都有在背后，默默看着你，陪着你。"}, {"type": "narr", "text": "你的体温透过毛衣传过来，带着一点洗衣液的味道。我在你背上，能听见你翻书的声音，一下，又一下。"}, {"type": "line", "speaker": "他", "text": "后来，你把更多时间交给了工作。我很少看见你开心的样子，也很少再来闹我。"}, {"type": "narr", "text": "你带我搬去了自己的房子，给我换了更大的软垫。可我总是跳上你的背，压着你，直到你笑着抱怨腿麻。"}, {"type": "line", "speaker": "他", "text": "你带我搬去了自己的房子，给我换了更大的软垫。但我还是喜欢趴在你的背上，压着你，直到你抱怨，腿都麻了。"}, {"type": "line", "speaker": "他", "text": "喜欢看你笑着喊我的名字，揉揉我的脑袋，用你的下巴，给我梳毛。"}, {"type": "narr", "text": "你的下巴轻轻蹭过我的头顶，一下一下，带着暖意。我眯起眼睛，喉咙里发出咕噜咕噜的声音。"}, {"type": "line", "speaker": "他", "text": "喜欢在冬日，阳光正好的午后，你眯着眼，和你一起晒太阳。"}, {"type": "narr", "text": "阳光透过玻璃落在我们身上，你半睡半醒，手搭在我背上。那时我就想，这样的日子，如果能再久一点就好了。"}, {"type": "line", "speaker": "他", "text": "我多想，能趴你再久一点，再久一点呢。"}, {"type": "narr", "text": "可是最近，我总觉得眼前蒙着一层雾。跳上沙发的时候，脚一软，差点摔下去。"}, {"type": "line", "speaker": "他", "text": "我先看不见。渐渐看不见。视力没有了依靠，也不能准确地判断跳跃的距离。"}, {"type": "narr", "text": "那天傍晚，我像往常一样想跳上沙发。起跳的瞬间，我算错了距离，整个身体撞在沙发边上，摔了下来。"}, {"type": "line", "speaker": "他", "text": "在第七次跳沙发的时候，我摔下来了。我就知道了，我要走了。"}, {"type": "narr", "text": "我趴在地上，缓了很久。你跑过来，把我抱起来，一遍遍问我怎么了。我蹭了蹭你的手心，心里说，别难过。"}, {"type": "line", "speaker": "他", "text": "你实际上对我说很羡慕我，能当一只猫咪。不会悲喜，也不会欣喜若狂。我这个淘气鬼。"}, {"type": "narr", "text": "可你不知道，我这一生所有的情绪，都给了你。开心是因为你，难过也是因为你。"}, {"type": "line", "speaker": "他", "text": "但是我是真的很爱你。所以这次就让我任性一回。下次见面，换我去找你。"}, {"type": "narr", "text": "我最后看了一眼你的睡颜。窗外的天边，泛起一线灰白。我站起身，轻轻地，从窗台跳了下去。"}, {"type": "line", "speaker": "他", "text": "等着那一天，我会蹲在家门口。你回来的时候，我就滚到你脚边。你一定可以认出我，然后，带我回家。对吗？"}, {"type": "narr", "text": "晨光落在我身上，我最后回头望了一眼那扇窗。窗里，你还在睡。而我这一世的心愿，已经了了。"}, {"type": "line", "speaker": "他", "text": "姐姐。一定是。所以，再见了。永远爱你的，猫咪。"}, {"type": "narr", "text": "后来的许多年，你总是会在家门口遇到一只猫。它不靠近，只是远远地看你，眼睛里有说不清的温柔。你知道，那是谁。"}]}, {"no": 34, "id": "EsjnNvBWCTQ", "title": "The wife who signed the contract without authorization", "title_zh": "擅自签下契约的妻子 (The wife who signed the contract without authorization)", "duration": "00:09:15", "link": "https://www.youtube.com/watch?v=EsjnNvBWCTQ", "enriched": true, "lines": [{"ts": "00:00:00", "text": "你给我查一下谁冒充身份签的合同。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:03", "text": "让签合同的马上给我收拾包袱滚蛋。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:07", "text": "等着吃苦头吧。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:00:10", "text": "夫人。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "你拦不住是吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:17", "text": "幸好我知道了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:21-00:00:31", "text": "你怎么回事（重复7次，已合并）。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "陈。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:35", "text": "你倒是很悠闲啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "马上给我滚到书房里。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:53", "text": "你先看看这合同。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:59", "text": "抖什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "谁允许你擅自做主的？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "真不愧是我的好老婆。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:01:11", "text": "还敢伪造我签名了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "你知道你这样做直接导致公司损失了五百万吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:19", "text": "行了我也不想打你了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "你那么在意你哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "那咱明天就去民政局办个离婚手续吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "回房间睡吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "我去客房睡。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "回去干嘛？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:44", "text": "不想离婚求我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "不要抓着我给我放手。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:53", "text": "我说你给我放手。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:57", "text": "你也不用跪了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "起来吧。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:07", "text": "你现在就可以她妈的滚了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "哭什么？", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:16", "text": "眼泪憋回去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "还跪着干什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "行。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "这是你自找的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "跟我来惩罚的事。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:02:39", "text": "爬过去是要你站起来的。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:44", "text": "把藤条拿过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:52", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:05", "text": "把它握住。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:12", "text": "要不是我发现的早。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "公司合计损失这五百万。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:20", "text": "屁股再撅高一点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "今天。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "50下藤条。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "不准躲。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:31", "text": "也不准动。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:34", "text": "更不准哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:36", "text": "没异议的话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "我们重新来过。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "听明白了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:43", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "给我姿势摆正了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:55", "text": "再扭来扭去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "我就绳子把你绑起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:04", "text": "报数报大声一点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "我没听见。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "你从头。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "继续报数。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "还敢犟嘴。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:25", "text": "那就从零开始报数吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "最后实际上你也不用报了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "我会打重一点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "你给我乖乖地受着。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:48", "text": "到墙角跪着去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "跪着了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:03", "text": "手放背后。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:08", "text": "不要给我搞小动作。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:13", "text": "好好想想你做的事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:18", "text": "小张什么事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "好我知道了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:41", "text": "你过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:45", "text": "你也不用跪了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:49", "text": "来你过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:53", "text": "你过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:57", "text": "你那个。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:59", "text": "十万的包子。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:01", "text": "还没找到。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "看你表情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "张秘书说的没错。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:10", "text": "是给承认了是吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:14", "text": "很好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "你真的很好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "你到底瞒了我多少事情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:27", "text": "不准哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:29", "text": "你还有脸哭啊！", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:06:32", "text": "把我的钱。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:06:34", "text": "拿着去给其他男人。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:37", "text": "还骗我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:40", "text": "哥哥你们俩有什么关系吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:06:45", "text": "哥哥叫得挺亲啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "从这个月开始。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:57", "text": "你的零花钱一分也没有了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:05", "text": "你自己好好反省一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:13-00:07:17", "text": "真的吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:07:19", "text": "上辈子欠了你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:21", "text": "好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "起来吧。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:26", "text": "别跪着了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:29", "text": "再跪习惯就要废了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32-00:07:35", "text": "过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:38-00:07:42", "text": "我给你上药。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:47-00:07:52", "text": "赛。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:57", "text": "我没有原谅你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:03", "text": "只是暂时先不打你了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "我也打累了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:08:10", "text": "暂时先不跟你离婚。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:14", "text": "但是再有下次。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:17", "text": "再有下次就不用说这些话了吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:21", "text": "忍着点马上涂好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:25", "text": "而且明天开始你也不用去公司了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:29", "text": "好好在家里面待着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:32", "text": "跳舞也好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:36", "text": "瑜伽也好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:40", "text": "美容也好随便你选。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:44", "text": "撒娇也没有用。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:47", "text": "还有就是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:50", "text": "把那个宠物伤了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:54", "text": "再有联系。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:57", "text": "你自己想象后果。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:01", "text": "去把温水喝了让我去睡觉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:01", "text": "我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:01", "text": "我今天晚上不是要处理你留下来的烂摊子吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:09:01", "text": "去睡觉。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "豪门夫妻管娇型。说话者是丈夫（被你叫「哥哥」），你是擅自伪造他签名签合同的「老婆」。情境起点：他查出合同损失五百万、怒而说要离婚，转而用藤条罚你五十下、不准躲不准哭，其间发现你把钱拿给别的「哥哥」、一气之下取消了你零花钱；罚完又心软给你上药、暂不打离婚，约法「再犯就后果自负」。整体是「犯大错后被丈夫藤条惩戒、再被心疼上药」型，基调愤怒、掌控、domestic 甜虐。", "behaviors": [{"desc": "发现你伪造他签名、公司损失五百万，说要离婚"}, {"desc": "把藤条拿过来递给你"}, {"desc": "罚你五十下藤条，不准躲、不准哭"}, {"desc": "让你姿势摆正，扭来扭去就绑起来"}, {"desc": "让你跪着、手放背后好好反省"}, {"desc": "让你过来、不用跪了"}, {"desc": "问你那个「哥哥」是谁、你俩啥关系"}, {"desc": "让你起来别跪，说给你上药"}, {"desc": "罚完让你去睡觉，自己收拾烂摊子"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、询问为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "职场", "治愈", "敏感"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": ["绑", "惩罚"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "书房的门被推开时，她正坐在沙发上喝茶，姿态悠闲。男人站在门口，手里的文件被攥得发皱，眼底翻涌着压抑的怒意。"}, {"type": "line", "speaker": "哥哥", "text": "你给我查一下谁冒充身份签的合同。让签合同的马上给我收拾包袱滚蛋。等着吃苦头吧。夫人。你拦不住是吧？幸好我知道了。你怎么回事。你怎么回事。陈。你倒是很悠闲啊！"}, {"type": "narr", "text": "她放下茶杯，脸色一点点白下去。他把合同摔在她面前的茶几上，声音冷得结冰。"}, {"type": "line", "speaker": "哥哥", "text": "马上给我滚到书房里。你先看看这合同。抖什么？谁允许你擅自做主的？真不愧是我的好老婆。还敢伪造我签名了。你知道你这样做直接导致公司损失了五百万吗？"}, {"type": "narr", "text": "她张了张嘴，想解释，却被他打断。他往后退了一步，目光里是失望，还有一种她看不懂的东西。"}, {"type": "line", "speaker": "哥哥", "text": "行了我也不想打你了。你那么在意你哥哥。那咱明天就去民政局办个离婚手续吧。回房间睡吧。我去客房睡。"}, {"type": "narr", "text": "她扑过去抓住他的手臂，眼泪一下子就掉了下来。他挣了两下，没挣开，声音哑下来。"}, {"type": "line", "speaker": "哥哥", "text": "回去干嘛？不想离婚求我。不要抓着我给我放手。我说你给我放手。你也不用跪了。起来吧。你现在就可以她妈的滚了。哭什么？眼泪憋回去。还跪着干什么？"}, {"type": "narr", "text": "她跪在地上，泪流满面，说什么也不肯起来。他站在原地看了她很久，最后闭了闭眼，像是下了什么决心。"}, {"type": "line", "speaker": "哥哥", "text": "行。这是你自找的。跟我来惩罚的事。爬过去是要你站起来的。把藤条拿过来。好。把它握住。要不是我发现的早。公司合计损失这五百万。屁股再撅高一点。"}, {"type": "line", "speaker": "哥哥", "text": "今天。50下藤条。不准躲。也不准动。更不准哭。没异议的话。我们重新来过。听明白了吗？好。给我姿势摆正了。再扭来扭去。我就绳子把你绑起来。报数报大声一点。我没听见。你从头。继续报数。还敢犟嘴。那就从零开始报数吧。最后实际上你也不用报了。我会打重一点。你给我乖乖地受着。"}, {"type": "narr", "text": "藤条破空的声音一下一下落下来。她咬着牙，一遍一遍地数着数，数到后面声音都抖了，却真的没有躲，没有哭出声。他收手时，额角也沁出了细汗。"}, {"type": "line", "speaker": "哥哥", "text": "到墙角跪着去。跪着了。手放背后。不要给我搞小动作。好好想想你做的事。"}, {"type": "narr", "text": "她背对着他，跪在墙角。屋里安静得只剩挂钟的滴答声。直到手机震动打破沉默，他接起电话，脸色忽然变了。"}, {"type": "line", "speaker": "哥哥", "text": "小张什么事。好我知道了。你过来。你也不用跪了。来你过来。你过来。你那个。十万的包子。还没找到。看你表情。张秘书说的没错。是给承认了是吧？很好。你真的很好。你到底瞒了我多少事情。"}, {"type": "narr", "text": "她茫然地看着他，像是没听懂他在说什么。他深吸一口气，声音里压着怒火，一字一句。"}, {"type": "line", "speaker": "哥哥", "text": "不准哭。你还有脸哭啊！把我的钱。拿着去给其他男人。还骗我。哥哥你们俩有什么关系吗？哥哥叫得挺亲啊！从这个月开始。你的零花钱一分也没有了。你自己好好反省一下。"}, {"type": "narr", "text": "她拼命摇头，想解释那笔钱的去向，声音哽咽得说不成句。他看着她，看着她哭得上气不接下气的样子，胸口那口气忽然就泄了。"}, {"type": "line", "speaker": "哥哥", "text": "真的吗？上辈子欠了你的。好了。起来吧。别跪着了。再跪习惯就要废了。过来。我给你上药。"}, {"type": "narr", "text": "他把她拉到沙发上趴好，拧开药膏，指尖蘸着药，轻轻抹过那些红肿的痕迹。她的肩背一抽一抽的，他手上的动作也跟着放得更轻。"}, {"type": "line", "speaker": "哥哥", "text": "赛。我没有原谅你。只是暂时先不打你了。我也打累了。暂时先不跟你离婚。但是再有下次。再有下次就不用说这些话了吧。忍着点马上涂好了。而且明天开始你也不用去公司了。好好在家里面待着。跳舞也好。瑜伽也好。美容也好随便你选。撒娇也没有用。"}, {"type": "line", "speaker": "哥哥", "text": "还有就是。把那个宠物伤了。再有联系。你自己想象后果。去把温水喝了让我去睡觉。我。我今天晚上不是要处理你留下来的烂摊子吗？去睡觉。"}]}, {"no": 35, "id": "IBW8yAnnywk", "title": "The world didn't make me so happy until I met you", "title_zh": "遇见你之前，世界从未让我如此幸福 (The world didn't make me so happy until I met you)", "duration": "00:04:28", "link": "https://www.youtube.com/watch?v=IBW8yAnnywk", "enriched": true, "lines": [{"ts": "00:00:00", "text": "怎么了，爸爸？很累了吧。爸爸辛苦了。来，哥哥给你按摩一下，躺我腿上好不好？", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:00:31", "text": "爸爸，怎么了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "哎呦，别哭。是心情不好吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:55", "text": "工作压力是不是大得吓人？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "来，哥哥。我知道爸爸最近很忙，可是再忙再累也要注意身体，你看——", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:01:19", "text": "你晚上两三点才睡，早上又早早起床上班，有时候连饭都顾不上吃。我真的很心疼，身体熬坏了怎么办？", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:01:32", "text": "我相信我的爸爸能照顾好自己。不过你好像从没告诉过我，为什么现在这么努力？你以前也是个无忧无虑的小女孩，今天却像变了个人。跟哥哥说说好不好？", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:01:44", "text": "我想成为和哥哥一样优秀的人。其实我倒不觉得自己多优秀，你本人就很棒。你再优秀我也怕自己配不上你。可我们为什么要在意别人的看法呢？", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:56", "text": "哎呦，你配得上我就行。你跟我在一起，只需考虑我一个人的感受，对不对？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "就像我跟你在一起时，也只考虑你的感受，对吧？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "别人说，哎呀你宝贝是个天仙，早晚会飞走。我不在乎，我就要爱你，对吧？", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:33", "text": "别人说，你老婆千年难得一见。我不在乎，我就要爱你。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:45", "text": "没有可是，不怕。遇见你已经是我的幸运，你那么懂事、温柔、善良。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:02:57", "text": "跟你在一起的每一天都特别开心。你才像一束光，照亮了我的生活，让原本灰暗的日子有了光亮。我特别喜欢你在身边跑来跑去的样子。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:03:09", "text": "还有你每天跟我讲工作里各种事，听你吐槽。你那副假装很舒服、其实在撒娇的吐槽样子，太可爱了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "还喜欢窝在怀里撒娇，缠着我给你讲睡前故事。", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:03:34", "text": "我没有不喜欢。因为是你呀，不管什么样子我都喜欢。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:03:50", "text": "你工作的时候如果想我了，发微信就好，我肯定不会不理你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "你想我的时候，我也在想你呀，小傻瓜。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:03:50", "text": "所以别在乎别人的看法。没有人能跟你比，怎么可能有人比得了你？", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:03:50", "text": "从你走进我心的那一刻起，这世界所有与我有关的美好，都与你有关。懂了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}], "scene": "日常宠溺撒娇型。说话者是「哥哥／抱抱」双重称呼下的恋人，你是被宠的「宝贝」。情境起点：你给疲惫的「抱抱」按摩、让他躺腿上，心疼他熬夜工作身体差；他反过来温柔安慰，说不在乎别人眼光、就是要爱你，你让他生活有了光亮，喜欢你撒娇、缠他讲睡前故事。整体是「双向宠溺＋情感告白」型，基调甜、治愈、纯爱。", "behaviors": [{"desc": "让你躺腿上，说给抱抱按摩好不好"}, {"desc": "看你哭，心疼你工作压力大、熬夜不吃饭"}, {"desc": "说不管你什么样子都喜欢"}, {"desc": "说想你就发消息、自己绝不会不理你，互相想念"}], "tone_summary": "（自动）爸爸视角独白，语气以平静、撒娇、命令为主，题材偏家庭/长辈。", "genre_tags": ["家庭/长辈", "治愈"], "genre_main": "家庭/长辈", "emotion_arc": "（自动）撒娇→命令→平静", "intensity": "中", "listener_role": "（自动）被爸爸倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "深夜的客厅只亮着一盏落地灯。她蜷在沙发角落，肩头微微耸动。门开了，他进来，一眼看见她眼角的湿痕，什么也没问，只是放轻脚步走到她身边，拍了拍自己的腿。"}, {"type": "line", "speaker": "他", "text": "来，躺我腿上，我给你按按，放松一下。"}, {"type": "narr", "text": "她顺从地枕上他的腿，他修长的手指落在她额角，一下一下轻轻揉着。"}, {"type": "line", "speaker": "他", "text": "怎么了？哎呦，别哭。是心情不好吗？"}, {"type": "narr", "text": "她摇了摇头，眼泪却掉得更凶。他叹了口气，指腹抹过她的脸颊。"}, {"type": "line", "speaker": "他", "text": "工作压力是不是大得吓人？我知道你最近很忙，可再忙再累也要注意身体。你看，你晚上两三点才睡，早上又早早起床上班，有时候连饭都顾不上吃。我真的很心疼，身体熬坏了怎么办？"}, {"type": "narr", "text": "她把脸埋进他手心里，闷闷地说了什么。他安静听完，把她额前的碎发拨到耳后。"}, {"type": "line", "speaker": "他", "text": "我相信你能照顾好自己。不过你好像从没告诉过我，为什么现在这么努力？你以前也是个无忧无虑的小女孩，今天却像变了个人。跟我说说，好不好？"}, {"type": "narr", "text": "她的声音闷闷的，说想成为和他一样优秀的人，又怕配不上。他轻轻笑了一下，低头在她发顶蹭了蹭。"}, {"type": "line", "speaker": "他", "text": "我倒不觉得自己多优秀，你本人就很棒。你再优秀我也怕自己配不上你。可我们为什么要在意别人的看法呢？哎呦，你配得上我就行。你跟我在一起，只需考虑我一个人的感受，对不对？"}, {"type": "narr", "text": "她仰起脸，眼圈还红着，嘴角却弯了起来。他捏了捏她的脸，继续数给她听。"}, {"type": "line", "speaker": "他", "text": "就像我跟你在一起时，也只考虑你的感受，对吧？别人说，哎呀你宝贝是个天仙，早晚会飞走。我不在乎，我就要爱你。别人说，你老婆千年难得一见。我不在乎，我就要爱你。"}, {"type": "line", "speaker": "他", "text": "没有可是，不怕。遇见你已经是我的幸运，你那么懂事、温柔、善良。"}, {"type": "narr", "text": "他顿了顿，声音低下来，像在说一件珍藏已久的心事。"}, {"type": "line", "speaker": "他", "text": "跟你在一起的每一天都特别开心。你才像一束光，照亮了我的生活，让原本灰暗的日子有了光亮。我特别喜欢你在身边跑来跑去的样子。"}, {"type": "line", "speaker": "他", "text": "还有你每天跟我讲工作里各种事，听你吐槽。你那副假装很舒服、其实在撒娇的吐槽样子，太可爱了。还喜欢窝在怀里撒娇，缠着我给你讲睡前故事。"}, {"type": "line", "speaker": "他", "text": "我没有不喜欢。因为是你呀，不管什么样子我都喜欢。"}, {"type": "narr", "text": "她在他怀里蹭了蹭，困意一点点漫上来。他放轻了声音，像哄小孩一样。"}, {"type": "line", "speaker": "他", "text": "你工作的时候如果想我了，发微信就好，我肯定不会不理你。你想我的时候，我也在想你呀，小傻瓜。"}, {"type": "line", "speaker": "他", "text": "所以别在乎别人的看法。没有人能跟你比，怎么可能有人比得了你？"}, {"type": "narr", "text": "夜风把窗帘吹得轻轻浮动。他拥着她，声音沉静而笃定。"}, {"type": "line", "speaker": "他", "text": "从你走进我心的那一刻起，这世界所有与我有关的美好，都与你有关。懂了吗？"}]}, {"no": 36, "id": "GCuv20AUZJQ", "title": "To be my girl, to be taken care of so that you don’t have to fend for yourself", "title_zh": "做我的女孩，由我来照顾你，你不必独自撑着 (To be my girl, to be taken care of so that you don't have to fend for yourself)", "duration": "00:08:10", "link": "https://www.youtube.com/watch?v=GCuv20AUZJQ", "enriched": true, "lines": [{"ts": "00:00:00", "text": "阿姨。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:02", "text": "行李收拾好了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:06", "text": "好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "妈跟你说了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "早饭我就不吃了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "等一下万一小宝醒过来。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:00:15", "text": "估计还得闹一顿。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:17", "text": "我在飞机上吃就行了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "对了阿姨。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "那个临走前给你说一下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "小宝的性子你也知道。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "我不在身边。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "指不定怎么闹呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:32", "text": "你呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:34", "text": "多担待担待。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "都辛苦辛苦了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:00:38", "text": "吃饭。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:41", "text": "吃饭的事一定要把他叫醒了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "鸡蛋胡萝卜。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "每天必须吃够量。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "无论他怎么闹。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "坚决不能心软。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "还有牛奶。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "牛奶也要让他喝。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "一个不注意啊！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "他转头的功夫就得喝光了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:00", "text": "到时候他要是记性低下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "非说自己喝掉了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "那他也没办法。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "所以得看住。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "他那些小聪明啊！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "有时候我都招架不住。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "呃。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "实在不行的话。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "有事打电话。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:20", "text": "好吧？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "对了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "还有。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "每天穿什么衣服。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:28", "text": "你前一天帮他放好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "放在床边就可以了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "别让他自己挑。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:35", "text": "从衣柜里乱翻。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "外面天不冷。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:01:39", "text": "他迷迷糊糊的随便穿两件就往外跑。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:41", "text": "要是到时候再感冒了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:43", "text": "我这两天又不在身边。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:01:46", "text": "然后还有。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "让他安排上。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "八点前必须到家。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "七点必须睡觉。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "每天要半个小时被音乐熏陶。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "我写在任务清单上这些呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:02:02", "text": "一定要每天落实。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:05", "text": "要是敢耍赖的话。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "就直接给我打电话吧。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:10", "text": "一天也不能让他松懈。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:13", "text": "他那个小子可能忽悠您。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "您啊！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "别到时候给他收买了就行。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:21", "text": "对了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "还有吃药。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "吃药这个千万别忘了。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:30", "text": "一吃过晚饭就得赶紧让他吃。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "我也不知道你能不能应付得了他。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "一到吃药时间就要找事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "一会儿上厕所。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "一会儿要写作业。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:43", "text": "一会儿装睡。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "又耍脾气又哭又闹的。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:48", "text": "有时候还非得哄几下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "才能哭哭啼啼地喝下去。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:53", "text": "所以这个。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "监督他吃药。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "可是个体力活。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "您啊！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "做好准备了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:05", "text": "好在一天也就一顿了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:08", "text": "他这个胃病不能含糊。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "还有晚上就麻烦您了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "晚上啊！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "一定要和小宝一起睡。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "他稍微热一点。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:20", "text": "就会蹬被子。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "您多留意留意。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "还有他那个。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "他的零食。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "就都藏在自己的衣柜上面。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "您时不时偷看一下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "有没有什么特别辣的？", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:03:37", "text": "就直接给扔掉就行了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "他也发现不了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:43", "text": "他有的吃就心满意足了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:46", "text": "哪还能记着自己藏啥？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "今天就别和他早起了。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:03:52", "text": "昨天晚上。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "这孩子折腾到大半夜的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "嗓子都哭哑了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:04:00", "text": "阿姨您等一下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:02", "text": "给他熬点粥喝。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "是啊！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "都是我管的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:09", "text": "从小我去哪儿他去哪儿。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:11", "text": "第一次不带他出门。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "想到不带他呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:04:15", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:04:17", "text": "没法带他呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:04:19", "text": "这次去工作。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "那边环境又这么恶劣。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:04:23", "text": "我又没时间照顾他。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:04:25", "text": "万一到时候水土不服。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:27", "text": "生点病什么的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:29", "text": "我不得心疼死。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:04:32", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:04:34", "text": "怎么可能？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "怎么能哄好啊？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "昨天晚上是哭累了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:04:42", "text": "然后自己慢慢睡着的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:47", "text": "所以我就不跟他道别了。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:04:49", "text": "看到哭。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:04:52", "text": "哎。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:54", "text": "我估计又走不了了。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:04:57", "text": "行。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "时间差不多了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:00", "text": "那先这样吧。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "等上了飞机。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:04", "text": "我就给你发消息。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "那我先走了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:09", "text": "等等。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:12", "text": "小宝醒了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:16", "text": "是不是在喊我？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:05:22", "text": "你怎么光着脚就跑下来了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:25-00:05:29", "text": "爸爸（重复3次，已合并）。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "哥哥抱着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:32-00:05:33", "text": "爸爸。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:35-00:05:37", "text": "在哪？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:38", "text": "我这不是在这吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:05:40", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:05:42", "text": "好啦好啦！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "不早了不早了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "那么闹。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:51", "text": "不哭不哭了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:05:54", "text": "不哭了不哭了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:05:56", "text": "爸爸乖乖。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:05:58", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:01", "text": "哪有不要你呀？", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:03", "text": "哥哥。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:05", "text": "怎么会不要爸爸呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:06:08", "text": "我恨不得一直把爸爸抱在怀里。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:10", "text": "我的乖宝贝。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:13", "text": "来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:15", "text": "过来。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:17", "text": "坐好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:22", "text": "下去。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:25", "text": "听话。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:27", "text": "过来啊！", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:30", "text": "下去。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:33", "text": "这才因为。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "小眼睛很肿着呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:06:35", "text": "不哭了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:06:36", "text": "爸爸。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:37", "text": "小眼睛很肿着呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:06:39", "text": "不哭了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:06:41", "text": "爸爸。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:44", "text": "宝贝。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:46", "text": "不是哥哥不带你去。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:48", "text": "我也跟你说了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "这次去那边呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:06:52", "text": "是有重要任务。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:54", "text": "要是带着小宝的话。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:56", "text": "很多事情也做不了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:58", "text": "是不是？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:00", "text": "理解理解我。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:02", "text": "爸爸。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:04", "text": "现在还剩十分钟。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:05", "text": "车子就要来接我了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:07", "text": "如果飞机起飞了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:09", "text": "爸爸。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:11", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:07:13", "text": "怎么又哭了？", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:07:15", "text": "好了好了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:17", "text": "别往我身上挂。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:07:19", "text": "听话。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:07:21", "text": "哥哥现在必须得走了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "好不好？", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:07:25", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:07:27", "text": "宝贝怎么这么不乖了？", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:07:29", "text": "是不是？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "下来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:34-00:07:36", "text": "阿姨。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:38", "text": "你拦着小宝。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:40", "text": "我来不及了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:43", "text": "宝贝。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:07:45", "text": "哥哥走了之后。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:47", "text": "一定要听阿姨的话。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "不能这样闹知道吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:07:52", "text": "不要不听话。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:07:55", "text": "不准这样喊。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:07:55", "text": "嗓子不要了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "做完事情。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "我们马上回来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "好不好？", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:07:55", "text": "不哭了不哭了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:07:55", "text": "哥哥真的来不及了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "阿姨小宝交给您了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "我先走了。", "speaker": "爸爸", "tone": "平静", "sound": []}], "scene": "兄长出差托付型（你扮演需要被照顾的「小宝／小孩」）。说话者是「哥哥」，出差前反复叮嘱阿姨如何照顾你——吃饭、喝奶、吃药、睡觉、藏零食都要盯紧；你光脚跑出来哭着抱住哥哥不让走，哥哥哄你、说此行有任务不能带、让阿姨拦着你，最后嘱咐听阿姨话。整体是「哥哥出差、小孩扮演撒娇挽留」型，基调宠溺、依依不舍、domestic。", "behaviors": [{"desc": "叮嘱阿姨照顾小宝的饮食、喝奶、吃药"}, {"desc": "交代晚上要和小宝一起睡、防踢被子"}, {"desc": "说你昨天哭到大半夜、嗓子都哭哑了"}, {"desc": "你光脚跑下来喊「抱抱」、哥哥把你抱起来"}, {"desc": "哄你不哭，说哥哥怎么会不要你、把你包在怀里"}, {"desc": "让你坐好、听话"}, {"desc": "让阿姨拦着小宝，说哥哥来不及了必须走"}, {"desc": "叮嘱你听阿姨话、嗓子别喊坏了"}], "tone_summary": "（自动）爸爸视角独白，语气以平静、撒娇、命令为主，题材偏校园/师生。", "genre_tags": ["校园/师生", "家庭/长辈", "治愈"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被爸爸倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "清晨，他拎着行李箱站在玄关，一边看表，一边对着阿姨细细叮嘱。语气里满是放心不下。"}, {"type": "line", "speaker": "哥哥", "text": "阿姨，行李收拾好了吗？好。妈跟你说了，早饭我就不吃了，等一下万一小宝醒过来，估计还得闹一顿，我在飞机上吃就行了。对了阿姨，临走前给你说一下。小宝的性子你也知道，我不在身边，指不定怎么闹呢？你呢，多担待担待，辛苦了辛苦了。吃饭，吃饭的事一定要把他叫醒了。鸡蛋、胡萝卜，每天必须吃够量，无论他怎么闹，坚决不能心软。还有牛奶，牛奶也要让他喝。一个不注意啊！他转头的功夫就得喝光了。到时候他要是记性低下，非说自己喝掉了，那他也没办法，所以得看住。他那些小聪明啊！有时候我都招架不住。"}, {"type": "narr", "text": "他顿了顿，又想起什么，继续交代。阿姨一边听一边点头。"}, {"type": "line", "speaker": "哥哥", "text": "实在不行的话，有事打电话，好吧？对了，还有。每天穿什么衣服，你前一天帮他放好，放在床边就可以了，别让他自己挑，从衣柜里乱翻。外面天不冷，他迷迷糊糊的随便穿两件就往外跑，要是到时候再感冒了，我这两天又不在身边。然后还有，让他安排好，八点前必须到家，七点必须睡觉，每天要半个小时被音乐熏陶，我写在任务清单上这些呢，一定要每天落实。要是敢耍赖的话，就直接给我打电话吧，一天也不能让他松懈。他那个小子可能忽悠您，您啊！别到时候给他收买了就行。"}, {"type": "narr", "text": "他看了一眼时间，语气加快，却还是忍不住把最重要的事说完。"}, {"type": "line", "speaker": "哥哥", "text": "对了，还有吃药。吃药这个千万别忘了。一吃过晚饭就得赶紧让他吃。我也不知道你能不能应付得了他，一到吃药时间就要找事，一会儿上厕所，一会儿要写作业，一会儿装睡，又耍脾气又哭又闹的，有时候还非得哄几下，才能哭哭啼啼地喝下去。所以这个，监督他吃药，可是个体力活。您啊！做好准备了。好在一天也就一顿了，他这个胃病不能含糊。还有晚上就麻烦您了，晚上啊！一定要和小宝一起睡。他稍微热一点就会蹬被子，您多留意留意。"}, {"type": "narr", "text": "他想了想，又补了一句，语气带着无奈的笑意。阿姨应着，接过他手里的钥匙。"}, {"type": "line", "speaker": "哥哥", "text": "还有他那个，他的零食就都藏在自己的衣柜上面，您时不时偷看一下，有没有什么特别辣的？就直接给扔掉就行了。他也发现不了，他有的吃就心满意足了，哪还能记着自己藏啥？今天就别和他早起了，昨天晚上，这孩子折腾到大半夜的，嗓子都哭哑了。阿姨您等一下，给他熬点粥喝。是啊！都是我管的。从小我去哪儿他去哪儿，第一次不带他出门。想到不带他呀！哎呀！没法带他呀！"}, {"type": "narr", "text": "他站在门口，看着屋里那个还睡着的小身影，声音低下来。"}, {"type": "line", "speaker": "哥哥", "text": "这次去工作，那边环境又这么恶劣，我又没时间照顾他，万一到时候水土不服，生点病什么的，我不得心疼死。哎呀！怎么可能？怎么能哄好啊？昨天晚上是哭累了，然后自己慢慢睡着的。所以我就不跟他道别了，看到哭，哎，我估计又走不了了。行，时间差不多了，那先这样吧。等上了飞机，我就给你发消息。那我先走了。"}, {"type": "narr", "text": "他刚要转身，楼上传来一声带着哭腔的喊声。他脚步一顿，果然，一个小身影光着脚跑下楼，扑进他怀里。"}, {"type": "line", "speaker": "哥哥", "text": "等等。小宝醒了，是不是在喊我？哎呀！你怎么光着脚就跑下来了？爸爸。哥哥抱着。爸爸。在哪？我这不是在这吗？哎呀！好啦好啦！不早了不早了。那么闹？不哭不哭了。爸爸乖乖。哎呀！哪有不要你呀？怎么会不要爸爸呢？我恨不得一直把爸爸抱在怀里，我的乖宝贝。"}, {"type": "narr", "text": "她埋在他怀里，哭得直抽。他低头看着她，语气带着心疼的温柔，却还是必须得走了。"}, {"type": "line", "speaker": "哥哥", "text": "来，过来，坐好。哎呀！下去，听话，过来啊！下去。这才乖。小眼睛还肿着呢？不哭了，爸爸。宝贝。不是哥哥不带你去，我也跟你说了，这次去那边呢，是有重要任务，要是带着小宝的话，很多事情也做不了，是不是？理解理解我。爸爸。现在还剩十分钟，车子就要来接我了。如果飞机起飞了，爸爸——哎呀！怎么又哭了？"}, {"type": "narr", "text": "她挂在他身上不肯松手。他低头，无奈地笑了，语气却还是得硬起来。"}, {"type": "line", "speaker": "哥哥", "text": "好了好了，别往我身上挂，听话。哥哥现在必须得走了，好不好？哎呀！宝贝怎么这么不乖了？是不是？下来。阿姨，你拦着小宝，我来不及了。宝贝，哥哥走了之后，一定要听阿姨的话，不能这样闹，知道吗？不要不听话。不准这样喊，嗓子不要了。做完事情，我们马上回来，好不好？不哭了不哭了。哥哥真的来不及了。阿姨，小宝交给您了。我先走了。"}, {"type": "narr", "text": "门在身后关上，她站在玄关，眼泪还挂在脸上。窗外，他的车缓缓驶远。她握着阿姨的手，在心里小声说——哥哥，早点回来。而那份被细细交代过的爱，她其实都听得懂。"}]}, {"no": 37, "id": "TUiNQL0e810", "title": "When you stay up late and get caught", "title_zh": "当你熬夜被抓个正着 (When you stay up late and get caught)", "duration": "00:08:29", "link": "https://www.youtube.com/watch?v=TUiNQL0e810", "enriched": true, "lines": [{"ts": "00:00:00", "text": "宝贝。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "哎呦。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "满眼都是你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:11", "text": "对呀，我回来了。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:14", "text": "这么想我吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:18", "text": "摸摸头。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "我的小宝贝。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:26", "text": "等一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "先别急着亲亲。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:31", "text": "我先问你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "小朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "我不在家这几天，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "有没有乖乖的？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:41", "text": "低着头不说话，什么意思？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "心虚了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:46", "text": "昨天晚上，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "某个小家伙晚上上网冲浪的时候，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:52", "text": "被我抓了个正着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:55", "text": "然后问他吧，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "他装看不见。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:00", "text": "不回我消息。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "在那里装睡。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "这个小家伙是谁啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "不说话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "你胆子挺大了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "老实交代。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "昨天晚上几点睡的？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "别支支吾吾的。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:23", "text": "回答。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "老实点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "来来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "你自己看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "十一点的时候你跟我说，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "困了，宝贝睡觉了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "哥哥晚安。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "今天要梦到哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "然后还有个梦啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:50", "text": "表面上看着挺乖的。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:52", "text": "每天晚上道晚安之后——", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "但是，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "实际行动呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:00", "text": "自己又玩到两三点。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:02:02", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:05", "text": "你可真行啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "没想到我的小朋友，", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:02:11", "text": "还有两副面孔啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "放假了就可以熬夜吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:16", "text": "第二天一觉睡到中午。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "谁给你定的这种作息？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "而且吃饭也不规律。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:28", "text": "难怪你最近总是跟我说你胃疼。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:31", "text": "还学会顶嘴了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "可以啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "学会得可真不少呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:42", "text": "我看你什么时候能认错。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "过来趴好。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:49", "text": "我数到三。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "慢一秒，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "加罚一下。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:03:00", "text": "一。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "二。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:08", "text": "不准哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:11", "text": "犯错的时候想什么了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "你是觉得糟蹋自己身体，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "很有意思是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "你知不知道，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:24", "text": "一听说你难受，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "我有多着急。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "我忙着把手头的事都做完，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "想快点回来照顾你。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:35", "text": "结果呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:37", "text": "你呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:40", "text": "没有听哥哥的话，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:43", "text": "好好照顾自己。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:46", "text": "这是其一。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "还顶嘴。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:52", "text": "然后每天骗我说乖乖睡觉，", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:59", "text": "背地里熬夜到这么晚。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:06", "text": "现在知道错了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:09", "text": "晚了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "自己数着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "刚刚那些，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "是对你不知错的教育。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "现在，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "是犯这些错，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "应该受到的惩罚。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:36", "text": "把手给我拿开。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:40", "text": "站起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:43", "text": "到明天，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "就好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "自己说，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:52", "text": "都哪里做错了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:55", "text": "站起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:58", "text": "到明天，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "就好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "自己说，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:08", "text": "都哪里做错了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "不该任性。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "不该不听话。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:18", "text": "还有呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:22", "text": "不该顶嘴。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "还有呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:29", "text": "我让你按时睡觉，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:31", "text": "作息不规律，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:34", "text": "不好好吃饭。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:36", "text": "你看你自己，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:39", "text": "有好好照顾自己吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:41", "text": "和你说过多少次，", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:05:44", "text": "不要总拿自己的身体开玩笑。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:05:46", "text": "为什么就是记不住？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:49", "text": "这次记住了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:51", "text": "要是以后再犯，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:54", "text": "怎么办？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "自己说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:59", "text": "会狠狠罚你的。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:06:01", "text": "如果再这样知错不改，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "那我也就没有再管你的必要了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:06", "text": "听到了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:06:09", "text": "怎么还越哭越厉害了呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:06:11", "text": "起来起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:13-00:06:15", "text": "起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:17", "text": "哥哥抱抱。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:19", "text": "抱抱。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:24-00:06:26", "text": "不凶你了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:28", "text": "不发坏脾气。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "抱抱抱。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:32", "text": "这么委屈的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "哥哥给你顺顺毛好吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:36", "text": "顺顺毛。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:39", "text": "宝贝你看。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:41", "text": "如果咱每天都按时睡觉，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:44", "text": "按时吃饭，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:46", "text": "那这样的一个小朋友，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:49", "text": "是不是就会健健康康的？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:51", "text": "也会有更多时间做其他的事情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:54", "text": "对不对？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:56", "text": "还有，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:59", "text": "不要总是为了减肥，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:01", "text": "就少吃饭。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:04", "text": "你现在这样就可爱。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:06", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:09", "text": "抱起来，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:11", "text": "软软的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:14", "text": "还香香的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:17", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:19", "text": "哥哥答应你，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:21", "text": "不会不管你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "但是，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:26", "text": "你要听话，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:28", "text": "要爱惜这个身体。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:30", "text": "知道吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:07:33", "text": "你以为哥哥心软。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:35", "text": "我也不想一会儿就来罚你了。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:07:37", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:40", "text": "那谁让这个小坏蛋，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:42", "text": "总是让我生气。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:44", "text": "还是得教育才可以。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:47", "text": "知道错了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:49", "text": "这才乖。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:51", "text": "不是吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:07:54", "text": "到睡觉时间。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:56", "text": "我知道现在到睡觉时间了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:59", "text": "你就是被罚怕了，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:08:01", "text": "才提醒我的。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:08:04", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "怎么这么可爱了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:09", "text": "不过今天呢，", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:08:12", "text": "今天可以睡晚一点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:16", "text": "这么些天没见到我，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:19", "text": "想不想。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "我也好想你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "让我看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "你哪里在笑了。", "speaker": "哥哥", "tone": "宠溺", "sound": []}], "scene": "熬夜被抓管娇型。说话者是「哥哥」，你是被抓包熬夜的「小朋友／小宝贝」。情境起点：他出差回来摸你头，揭穿你表面说「困了晚安」、背地里玩到两三点，因作息紊乱、胃疼、顶嘴而让你趴好挨罚、罚完再抱你顺毛，立规矩「以后乖乖睡觉吃饭」。整体是「揭穿两面派＋打屁股惩罚后的温柔安抚」型，基调掌控、甜虐、宠。", "behaviors": [{"desc": "摸摸你的头，叫小宝贝"}, {"desc": "问你这几天有没有乖，揭穿你昨晚熬夜"}, {"desc": "让你看聊天记录：11点说困、实际玩到两三点"}, {"desc": "让你过来趴好，数到三慢一秒加十下"}, {"desc": "让你把手拿开、站起来到明天跪好"}, {"desc": "让你认错：不该不听话、不该顶嘴"}, {"desc": "抱抱你、给你顺顺毛说不凶你了"}, {"desc": "说今天可以睡晚点，问想不想他"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、询问、命令为主，题材偏治愈。", "genre_tags": ["治愈"], "genre_main": "治愈/宠溺", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "门开了，他拎着行李进门，就看见她扑过来。他接住她，揉了揉她的头发，语气带着宠溺，话锋却一转。"}, {"type": "line", "speaker": "哥哥", "text": "宝贝，哎呦，满眼都是你。对呀，我回来了。这么想我吗？摸摸头，我的小宝贝。等一下，先别急着亲亲。我先问你，小朋友，我不在家这几天，有没有乖乖的？低着头不说话，什么意思？心虚了。"}, {"type": "narr", "text": "她埋在他怀里，闷闷地不敢抬头。他叹了口气，语气带着一点秋后算账的意味。"}, {"type": "line", "speaker": "哥哥", "text": "昨天晚上，某个小家伙晚上上网冲浪的时候，被我抓了个正着。然后问他吧，他装看不见，不回我消息，在那里装睡。这个小家伙是谁啊！不说话？你胆子挺大了。老实交代，昨天晚上几点睡的？别支支吾吾的，回答。好，老实点。来来，你自己看看。"}, {"type": "narr", "text": "他拿出手机，翻出聊天记录，念给她听。她的脸一点点烧起来。"}, {"type": "line", "speaker": "哥哥", "text": "十一点的时候你跟我说，困了，宝贝睡觉了，哥哥晚安，今天要梦到哥哥。然后还有个梦啊！表面上看着挺乖的。每天晚上道晚安之后——但是，实际行动呢？自己又玩到两三点，是不是？你可真行啊！没想到我的小朋友，还有两副面孔啊！放假了就可以熬夜吗？第二天一觉睡到中午。谁给你定的这种作息？"}, {"type": "narr", "text": "她小声辩解了一句。他看着她，语气带着无奈的火气。"}, {"type": "line", "speaker": "哥哥", "text": "而且吃饭也不规律，是不是？难怪你最近总是跟我说你胃疼。还学会顶嘴了。可以啊！学会得可真不少呢？我看你什么时候能认错。过来趴好。我数到三，慢一秒，加罚一下。一，二。不准哭。犯错的时候想什么了。你是觉得糟蹋自己身体，很有意思是不是？"}, {"type": "narr", "text": "巴掌一下一下落下来，她咬着牙，一声不吭。他一边打，一边带着后怕的心疼。"}, {"type": "line", "speaker": "哥哥", "text": "你知不知道，一听说你难受，我有多着急。我忙着把手头的事都做完，想快点回来照顾你。结果呢？你呢？没有听哥哥的话，好好照顾自己。这是其一。还顶嘴。然后每天骗我说乖乖睡觉，背地里熬夜到这么晚。现在知道错了？晚了。自己数着。刚刚那些，是对你不知错的教育。现在，是犯这些错应该受到的惩罚。把手给我拿开。站起来。到明天，就好了。"}, {"type": "narr", "text": "她带着哭腔，一声一声报着数，把错都认了一遍。他听着，语气终于缓下来。"}, {"type": "line", "speaker": "哥哥", "text": "自己说，都哪里做错了。不该任性。不该不听话。还有呢？不该顶嘴。还有呢？我让你按时睡觉，作息不规律，不好好吃饭。你看你自己，有好好照顾自己吗？和你说过多少次，不要总拿自己的身体开玩笑。为什么就是记不住？这次记住了？要是以后再犯，怎么办？自己说。会狠狠罚你的。"}, {"type": "narr", "text": "她哭得一抽一抽的。他放下手里的东西，把人捞进怀里，语气软下来。"}, {"type": "line", "speaker": "哥哥", "text": "如果再这样知错不改，那我也就没有再管你的必要了。听到了吗？怎么还越哭越厉害了呢？起来起来，起来。哥哥抱抱。抱抱。不凶你了，不发坏脾气。抱抱抱。这么委屈的。哥哥给你顺顺毛，好吧？顺顺毛。"}, {"type": "narr", "text": "她靠在他怀里，抽噎着渐渐平静下来。他一下一下顺着她的背，语气带着心疼的耐心。"}, {"type": "line", "speaker": "哥哥", "text": "宝贝你看，如果咱每天都按时睡觉，按时吃饭，那这样的一个小朋友，是不是就会健健康康的？也会有更多时间做其他的事情，对不对？还有，不要总是为了减肥就少吃饭。你现在这样就可爱，是不是？抱起来，软软的，还香香的。"}, {"type": "narr", "text": "她在他怀里，声音闷闷的。他低头看着她，语气带着郑重的承诺。"}, {"type": "line", "speaker": "哥哥", "text": "好。哥哥答应你，不会不管你的。但是，你要听话，要爱惜这个身体，知道吗？你以为哥哥心软，我也不想一会儿就来罚你了，是不是？那谁让这个小坏蛋，总是让我生气，还是得教育才可以。知道错了，这才乖，不是吗？"}, {"type": "narr", "text": "她小声提醒他该睡觉了。他看着她，忽然笑了，语气带着一点促狭的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "到睡觉时间？我知道现在到睡觉时间了。你就是被罚怕了，才提醒我的，是不是？怎么这么可爱了？不过今天呢，今天可以睡晚一点。这么些天没见到我，想不想？我也好想你。让我看看，你哪里在笑。"}, {"type": "narr", "text": "她终于破涕为笑。他低头看着她，也跟着笑了。这一晚的罚，到底还是被那句“我也好想你”轻轻化解了。明天开始，按时睡觉，按时吃饭——她知道的，有人会一直替她记着。"}]}, {"no": 38, "id": "608yArRhfQ8", "title": "When your boyfriend has a twin brother（Double track）", "title_zh": "当你的男友有个双胞胎兄弟（双轨） (When your boyfriend has a twin brother（Double track）)", "duration": "00:07:10", "link": "https://www.youtube.com/watch?v=608yArRhfQ8", "enriched": true, "lines": [{"ts": "00:00:00", "text": "哎，怎么了，老婆？别急，别急，松开我。对呀，再给你做蛋糕呢，抹每一块的奶油都是特地给你调的，来，尝一口。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:22", "text": "我给你刮一点，用什么勺子呀。你平时被我使唤的时候也没这么多事。哎，快要掉了，要掉了。好吃吧？那是你老公聪明，学起来当然快了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:45", "text": "我切点水果，装饰蛋糕就交给老婆了。别闹，老婆，老婆，老婆——好了，不逗你了。蛋糕这就做好了，等会儿他就回来了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:08", "text": "衣服穿好。这么热的天，你自己摸摸，光是穿个围裙都热得要死。再说了，我和弟弟打小就长在一起，看个上半身有什么。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "老婆想看还不好意思。平时总说摸不够的时候怎么不害羞？睡着了迷迷糊糊地摸，那时候倒不害羞了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "好了好了，不行了。那当然了，过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:16", "text": "我回来了。小心点，多嘴什么。你在干嘛？哥，你老婆又把我当成你了。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:39", "text": "继续啊，还是让嫂子自己说吧。怎么不说？那你说。不过就是嫂子把我当成你了，嫂子抱我的时候，我怎么能推开她呢？", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:02:57", "text": "那不是有点让她失望吗？嫂子红着脸跟我说想亲的时候，我怎么拒绝得了？嫂子，是吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "行了行了，别说了。抬头，看着我。到底怎么才能分清楚我们俩？哥哥，你说我们长得都一样，分那么清楚干嘛。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:33", "text": "而且你一点都不关心你老公，万一人家是故意的呢，是吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:51", "text": "姐姐，你说，你到底是不是故意分不清楚？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:09", "text": "去把你眼罩摘下来。哥，你是不是吃醋了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:27", "text": "脱掉。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:45", "text": "趴在料理台上。不要？害羞？刚才你和他抱在一起的时候也没见你害羞。快点。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:03", "text": "从现在开始，每打一下你都要说清是谁打的，猜错一次，加罚一次。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:05:21", "text": "姐姐，你猜错了。我怎么舍得这么用力打你呢？有点可惜呢。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:39", "text": "错了。惩罚的时候，我不会安慰性地扶你。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:05:57", "text": "行了，起来吧。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:57", "text": "看姐姐这屁股红的。哥，你有点不怜香惜玉了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:57", "text": "跟我进来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:57", "text": "姐姐，我准备了礼物。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:57", "text": "现在，向我展示你的礼物。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:57", "text": "姐姐，别动啊，我帮你推一下腰。别怕，我哥在工作，不会来的。", "speaker": "哥哥", "tone": "命令", "sound": []}], "scene": "双胞胎兄弟误认扮演。说话者是「哥哥／老公」，你是分不清双胞胎兄弟的妻子。情境起点：哥哥在厨房做蛋糕喂你，弟弟回来后发现你把他当成哥哥又亲又抱，于是兄弟联手「惩罚」你——让你戴眼罩趴料理台，每打一下要说出是谁打的、猜错加罚；最后弟弟献上「礼物」、帮你推腰。整体是「老婆认错人、双男主轮流调娇」型，基调俏皮、吃醋、暧昧甜虐。", "behaviors": [{"desc": "哥哥在厨房做蛋糕、特调奶油喂你一口"}, {"desc": "弟弟回来，说你又把他当成哥哥亲抱"}, {"desc": "让你脱眼罩、趴在料理台上"}, {"desc": "打一下要你说清是谁打的，猜错加三下"}, {"desc": "罚完让你起来，说看这屁股红的"}, {"desc": "弟弟说准备了礼物，帮你推一下腰"}], "tone_summary": "（自动）哥哥视角独白，语气以命令、平静、询问为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）命令→平静", "intensity": "中偏高", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "厨房里飘着奶油的甜香。他系着围裙站在料理台前，正专心给蛋糕胚抹面，余光瞥见有人从背后挂上来，胳膊勒住他的腰。"}, {"type": "line", "speaker": "哥哥", "text": "哎，怎么了，老婆？别急，别急，松开我。对呀，再给你做蛋糕呢，抹每一块的奶油都是特地给你调的，来，尝一口。"}, {"type": "narr", "text": "他刮了一小勺奶油递过去，看她抿着嘴凑上来，指尖轻轻托住她的下巴。"}, {"type": "line", "speaker": "哥哥", "text": "我给你刮一点，用什么勺子呀。你平时被我使唤的时候也没这么多事。哎，快要掉了，要掉了。好吃吧？那是你老公聪明，学起来当然快了。"}, {"type": "narr", "text": "他切好水果，把裱花袋塞进她手里，说装饰的活儿交给老婆。她正闹着不干，他低头在她耳边笑了一声，又直起身。"}, {"type": "line", "speaker": "哥哥", "text": "我切点水果，装饰蛋糕就交给老婆了。别闹，老婆，老婆，老婆——好了，不逗你了。蛋糕这就做好了，等会儿他就回来了。"}, {"type": "narr", "text": "她只穿了件围裙，在厨房里转来转去。他皱眉，拿了件衣服给她披上。"}, {"type": "line", "speaker": "哥哥", "text": "衣服穿好。这么热的天，你自己摸摸，光是穿个围裙都热得要死。再说了，我和弟弟打小就长在一起，看个上半身有什么。"}, {"type": "line", "speaker": "哥哥", "text": "老婆想看还不好意思。平时总说摸不够的时候怎么不害羞？睡着了迷迷糊糊地摸，那时候倒不害羞了。"}, {"type": "narr", "text": "他话没说完就被她羞恼地推了一把，笑着把她往怀里一带。就在这时，门口传来钥匙转动的声音，另一道一模一样的嗓音响起。"}, {"type": "line", "speaker": "弟弟", "text": "我回来了。小心点，多嘴什么。你在干嘛？哥，你老婆又把我当成你了。"}, {"type": "narr", "text": "她这才发现自己扑错了人，涨红了脸往后缩。弟弟却弯起眼睛，一副无辜的模样，看向哥哥。"}, {"type": "line", "speaker": "弟弟", "text": "继续啊，还是让嫂子自己说吧。怎么不说？那你说。不过就是嫂子把我当成你了，嫂子抱我的时候，我怎么能推开她呢？那不是有点让她失望吗？嫂子红着脸跟我说想亲的时候，我怎么拒绝得了？嫂子，是吧？"}, {"type": "narr", "text": "哥哥的脸一点点沉下来。他伸手把愣住的她拉到自己身边，捏着她的下巴抬起来。"}, {"type": "line", "speaker": "哥哥", "text": "行了行了，别说了。抬头，看着我。到底怎么才能分清楚我们俩？"}, {"type": "line", "speaker": "弟弟", "text": "哥，你说我们长得都一样，分那么清楚干嘛。而且你一点都不关心你老公，万一人家是故意的呢，是吗？"}, {"type": "narr", "text": "她站在两兄弟中间，看看这个又看看那个，一时分不清谁是谁。哥哥眯起眼，语气带着一点危险的意味。"}, {"type": "line", "speaker": "哥哥", "text": "姐姐，你说，你到底是不是故意分不清楚？去把你眼罩摘下来。"}, {"type": "line", "speaker": "弟弟", "text": "哥，你是不是吃醋了？"}, {"type": "line", "speaker": "哥哥", "text": "脱掉。趴在料理台上。不要？害羞？刚才你和他抱在一起的时候也没见你害羞。快点。"}, {"type": "narr", "text": "厨房里安静了一瞬。她咬着唇，慢慢伏下去。哥哥的声音从身后传来，平静却不容拒绝。"}, {"type": "line", "speaker": "哥哥", "text": "从现在开始，每打一下你都要说清是谁打的，猜错一次，加罚一次。"}, {"type": "narr", "text": "第一下落下。她吃痛，小声报出名字，却见眼前的人轻轻笑了，那笑意和哥哥平时截然不同。"}, {"type": "line", "speaker": "弟弟", "text": "姐姐，你猜错了。我怎么舍得这么用力打你呢？有点可惜呢。"}, {"type": "line", "speaker": "哥哥", "text": "错了。惩罚的时候，我不会安慰性地扶你。"}, {"type": "narr", "text": "几下过后，她伏在料理台上喘着气，脸颊烫得厉害。身后的人终于收了手，语气缓下来。"}, {"type": "line", "speaker": "哥哥", "text": "行了，起来吧。看姐姐这屁股红的。"}, {"type": "line", "speaker": "弟弟", "text": "哥，你有点不怜香惜玉了。"}, {"type": "narr", "text": "哥哥没理他，牵起她的手往房间走。弟弟也跟了上来，在她耳边压低了声音。"}, {"type": "line", "speaker": "弟弟", "text": "跟我进来。姐姐，我准备了礼物。"}, {"type": "narr", "text": "房间里只开着一盏小灯。她看着弟弟弯下腰来，指尖抵住她的腰，声音又轻又软。"}, {"type": "line", "speaker": "弟弟", "text": "现在，向我展示你的礼物。姐姐，别动啊，我帮你推一下腰。别怕，我哥在工作，不会来的。"}]}]);